import { MeshPhysicalNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { mix, color, uv, smoothstep, vec3 } from 'three/tsl';
import { gsap } from 'gsap';
import { depthRotate } from '@/primitives';

export default function createNode(config, ctx) {
  const { Group, Mesh, OctahedronGeometry, PlaneGeometry, Shape, ExtrudeGeometry, DirectionalLight, Vector2, Color } = ctx.THREE;

  // Root group
  const root = new Group();

  // -------------------------------------------------
  // Backdrop gradient plane (7 x 6 units, z = -2.5)
  const backdropGeom = new PlaneGeometry(7, 6);
  const backdropMat = new MeshStandardNodeMaterial();
  // Simple vertical gradient from inset #0b0b10 to #16161d
  const gradColorNode = mix(
    color('#0b0b10'),
    color('#16161d'),
    uv().y
  );
  backdropMat.colorNode = gradColorNode;
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  backdrop.rotation.x = -Math.PI / 2;
  root.add(backdrop);

  // -------------------------------------------------
  // Triangular prism geometry
  const side = 1.2;
  const h = (Math.sqrt(3) / 2) * side;
  const shape = new Shape();
  shape.moveTo(0, h / 3);
  shape.lineTo(-side / 2, -h / 3 * 2);
  shape.lineTo(side / 2, -h / 3 * 2);
  shape.closePath();
  const prismGeom = new ExtrudeGeometry(shape, { depth: 1.8, bevelEnabled: false });
  const prismMat = new MeshPhysicalNodeMaterial({
    transmission: 1.0,
    thickness: 0.9,
    ior: 1.55,
    iridescence: 1.0,
    iridescenceIOR: 1.3,
    iridescenceThicknessRange: new Vector2(120, 480),
    roughness: 0.08,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    attenuationColor: new Color('#e8ecf2'),
    attenuationDistance: 2.5,
    color: new Color('#ffffff')
  });
  // Optional dispersion via node (simple RGB offset)
  const disp = mix(
    mix(color('#ff0000'), color('#00ff00'), uv().x),
    color('#0000ff'),
    uv().y
  );
  // Note: full physical dispersion is handled by the material; this node placeholder
  // could be hooked to refractionNode if needed.
  const prism = new Mesh(prismGeom, prismMat);
  prism.rotation.z = THREE.MathUtils.degToRad(12);
  prism.rotation.y = THREE.MathUtils.degToRad(20);
  root.add(prism);

  // -------------------------------------------------
  // Emissive core (octahedron)
  const coreGeom = new OctahedronGeometry(0.35);
  const coreMat = new MeshStandardNodeMaterial({
    color: new Color('#000000'),
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 2.2,
    metalness: 0,
    roughness: 0.5,
    transparent: true
  });
  const core = new Mesh(coreGeom, coreMat);
  core.position.set(0, 0, 0);
  root.add(core);

  // -------------------------------------------------
  // Back rim light
  const rimLight = new DirectionalLight(new Color('#a0cfff'), 0.8);
  rimLight.position.set(-2, 1, -2); // behind‑left
  root.add(rimLight);

  // -------------------------------------------------
  // Caustic streak plane on floor
  const causticGeom = new PlaneGeometry(2.4, 0.5);
  const causticMat = new MeshStandardNodeMaterial({ transparent: true, opacity: 0.35 });
  // Gradient emissive across X
  const emissiveGrad = mix(
    mix(color('#ff2a38'), color('#e8ecf2'), smoothstep(0.2, 0.5, uv().x)),
    color('#9fb0c4'),
    smoothstep(0.5, 0.8, uv().x)
  );
  causticMat.emissiveNode = emissiveGrad;
  const caustic = new Mesh(causticGeom, causticMat);
  caustic.rotation.x = -Math.PI / 2;
  caustic.position.set(0, -1.1, 0);
  root.add(caustic);

  // -------------------------------------------------
  // Text content via font atlas
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const opts = {
      fontSize: item.typography?.fontSize ?? (item.role === 'headline' ? 68 : 18),
      color: '#e8ecf2',
      align: 'center'
    };
    const textObj = ctx.fontAtlas.createText(item.text, opts);
    const yPos = item.role === 'headline' ? -1.75 : -2.25;
    textObj.position.set(0, yPos, 0);
    root.add(textObj);
  }

  // -------------------------------------------------
  // Cinematic primitive: depth‑rotate on hover
  const dr = ctx.primitives['depth-rotate'](root, { maxDeg: 10 });
  // Store for cleanup
  root.userData._primitives = [dr];

  // Cleanup routine
  root.userData.cleanup = () => {
    // primitives cleanup
    if (root.userData._primitives) {
      for (const p of root.userData._primitives) {
        if (p && typeof p.cleanup === 'function') p.cleanup();
      }
    }
    // Dispose meshes
    root.traverse((obj) => {
      if (obj.isMesh) {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) obj.material.dispose();
      }
    });
    // Kill any GSAP timelines (none created directly here)
    gsap.globalTimeline.clear();
  };

  // No interaction handlers required for this spec
  root.userData.handlers = {};

  return root;
}
